import {appearances} from './tierlist-appearances.mjs?v=1';
export {appearances};
export const modes=['Horde','Arena','Boss','Custom'];
export const defaults=()=>({schema:1,title:'My Tatari tierlist',gameMode:'Custom',appearance:'normal',imageStyle:'icon',tier:4,notes:'',background:'#fffef1',view:'list',chart:{left:'Low',right:'High',top:'High',bottom:'Low',positions:{}},rows:['S','A','B','C','D','E'].map((label,i)=>({label,color:['#ff7f7f','#ffbf7f','#ffdf7f','#ffff7f','#bfff7f','#7fff7f'][i],units:[]}))});
export const formFor=(unit,tier)=>unit.forms.find(f=>f.evolution===tier)||unit.forms.at(-1);
export function entryFor(units,key,tier=4){if(appearances[key]){const a=appearances[key],unit=units.find(u=>u.id===a.unit),form=unit?.forms.find(f=>f.evolution===a.tier);return form?{unit,form,key,src:a.src,appearance:a.label}:null;}if(!/^[0-9]{1,2}(?:-[1-4])?$/.test(String(key)))return null;const [id,evolution]=String(key).split('-').map(Number),unit=units.find(u=>u.id===id);if(!unit)return null;const form=evolution?unit.forms.find(f=>f.evolution===evolution):formFor(unit,tier||4);return form?{unit,form,key:unit.id+'-'+form.evolution,src:'tatari-data/'+form.playerhead,appearance:'Normal'}:null}
export function cleanList(raw,units){if(!raw||raw.schema!==1||![0,1,2,3,4].includes(raw.tier)||!Array.isArray(raw.rows)||raw.rows.length<1||raw.rows.length>20)throw Error('This tierlist link is invalid.');const seen=new Set(),valid=key=>entryFor(units,key,raw.tier)?.key;const chart={...defaults().chart};for(const side of ['left','right','top','bottom'])chart[side]=String(raw.chart?.[side]||chart[side]).slice(0,40);chart.positions={};for(const [key,p] of Object.entries(raw.chart?.positions||{})){const id=valid(key);if(id&&p&&Number.isFinite(p.x)&&Number.isFinite(p.y))chart.positions[id]={x:Math.max(0,Math.min(100,p.x)),y:Math.max(0,Math.min(100,p.y))}}return {schema:1,title:String(raw.title||'My Tatari tierlist').slice(0,80),gameMode:modes.includes(raw.gameMode)?raw.gameMode:'Custom',tier:raw.tier,imageStyle:raw.imageStyle==='character'?'character':'icon',appearance:['normal','glitter','sparkle'].includes(raw.appearance)?raw.appearance:'normal',notes:String(raw.notes||'').slice(0,500),...(raw.shareAuthor?{shareAuthor:String(raw.shareAuthor).slice(0,80)}:{}),background:/^#[0-9a-f]{6}$/i.test(raw.background||'')?raw.background:'#fffef1',view:raw.view==='chart'?'chart':'list',chart,rows:raw.rows.map(r=>{if(!r||!/^#[0-9a-f]{6}$/i.test(r.color)||!Array.isArray(r.units))throw Error('Invalid tierlist row.');return {label:String(r.label||'?').slice(0,16),color:r.color,units:r.units.map(valid).filter(id=>{if(!id||seen.has(id))return false;seen.add(id);return true})}})}}
export function moveUnit(state,id,row,index){state.rows.forEach(r=>r.units=r.units.filter(u=>u!==id));if(row>=0){const list=state.rows[row].units;list.splice(index===undefined?list.length:Math.max(0,Math.min(index,list.length)),0,id)}}
export function encodeList(s){return btoa(String.fromCharCode(...new TextEncoder().encode(JSON.stringify(s))))}
export function decodeList(s){if(s.length>60000)throw Error('Tierlist link is too long.');return JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(s),c=>c.charCodeAt(0))))}

export function artworkFor(entry,imageStyle='icon'){return imageStyle==='character'&&entry.appearance==='Normal'&&entry.form.portrait?'tatari-data/'+entry.form.portrait:entry.src}
